{
  "name": "@paysdoc/devplatform",
  "version": "0.0.0-development",
  "description": "Forge ports and adapters (GitHub, GitLab, Jira) over a forge-neutral git/worktree core",
  "type": "module",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/paysdoc/devplatform.git"
  },
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js",
      "default": "./dist/index.js"
    },
    "./providers": {
      "types": "./dist/providers/index.d.ts",
      "import": "./dist/providers/index.js",
      "default": "./dist/providers/index.js"
    },
    "./git": {
      "types": "./dist/git/index.d.ts",
      "import": "./dist/git/index.js",
      "default": "./dist/git/index.js"
    },
    "./package.json": "./package.json"
  },
  "files": ["dist", "README.md", "LICENSE"],
  "sideEffects": false,
  "publishConfig": {
    "access": "public"
  },
  "engines": {
    "node": ">=20"
  },
  "scripts": {
    "typecheck": "tsc --noEmit",
    "test:unit": "vitest run",
    "test": "tsc --noEmit",
    "clean": "node -e \"require('node:fs').rmSync('dist',{recursive:true,force:true})\"",
    "build": "bun run clean && tsc -p tsconfig.build.json",
    "smoke:package": "bunx tsx scripts/smokePackage.ts",
    "prepack": "bun run build"
  },
  "devDependencies": {
    "@types/node": "^25.3.0",
    "tsx": "^4.19.3",
    "typescript": "^5.7.3",
    "vitest": "^4.1.0"
  }
}

import { defineConfig } from 'vitest/config';

const junitReportPath = process.env.ADW_UNIT_TEST_REPORT_PATH;

export default defineConfig({
  test: {
    include: ['src/**/__tests__/**/*.test.ts'],
    reporters: junitReportPath
      ? ['default', ['junit', { outputFile: junitReportPath }]]
      : ['default'],
  },
});

/**
 * Asserts the `exports`/`files` contract in `package.json` matches the three
 * documented entry points and that every mapped `dist/` target has a
 * corresponding `src/` source file, so the manifest stays enforced by the
 * unit-test gate without requiring a build.
 */
import { describe, expect, it } from 'vitest';
import * as fs from 'node:fs';
import * as path from 'node:path';
import { fileURLToPath } from 'node:url';

const REPO_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');

interface ExportCondition {
  types?: string;
  import?: string;
  default?: string;
}

interface PackageManifest {
  type?: string;
  files?: string[];
  exports?: Record<string, ExportCondition | string>;
}

function readPackageManifest(): PackageManifest {
  const raw = fs.readFileSync(path.join(REPO_ROOT, 'package.json'), 'utf-8');
  return JSON.parse(raw) as PackageManifest;
}

describe('package.json — exports/files contract', () => {
  const pkg = readPackageManifest();

  it('declares exactly the four documented exports keys', () => {
    expect(Object.keys(pkg.exports ?? {}).sort()).toEqual(['.', './git', './package.json', './providers']);
  });

  it('type is "module"', () => {
    expect(pkg.type).toBe('module');
  });

  it('files is exactly ["dist", "README.md", "LICENSE"] and contains no src', () => {
    expect(pkg.files).toEqual(['dist', 'README.md', 'LICENSE']);
    expect(pkg.files ?? []).not.toContain('src');
  });

  const subpathToSource: Record<string, string> = {
    '.': 'src/index.ts',
    './providers': 'src/providers/index.ts',
    './git': 'src/git/index.ts',
  };

  it.each(Object.entries(subpathToSource))('exports[%s] types/import point under dist/ and have a corresponding source file', (subpath, sourcePath) => {
    const condition = pkg.exports?.[subpath];
    expect(condition, `exports["${subpath}"] is missing`).toBeTypeOf('object');
    const { types, import: importCond } = condition as ExportCondition;

    expect(types, `exports["${subpath}"].types`).toMatch(/^\.\/dist\//);
    expect(importCond, `exports["${subpath}"].import`).toMatch(/^\.\/dist\//);

    expect(fs.existsSync(path.join(REPO_ROOT, sourcePath)), `expected source file ${sourcePath} to exist`).toBe(true);
  });

  it('exports["./package.json"] points at the manifest itself', () => {
    expect(pkg.exports?.['./package.json']).toBe('./package.json');
  });
});

/**
 * Static import-graph walker asserting the public entry points stay layered:
 * `"./git"` and the root entry must never reach an adapter module or
 * `forgeProviders`, so a consumer importing just the git core (or just the
 * domain model) never pulls provider code into their bundle. Walks `src/`
 * directly (not `dist/`) so this runs in the normal unit-test gate without
 * requiring a build.
 */
import { describe, expect, it } from 'vitest';
import * as fs from 'node:fs';
import * as path from 'node:path';
import { fileURLToPath } from 'node:url';

const REPO_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');

function extractRelativeSpecifiers(content: string): string[] {
  const specifiers: string[] = [];
  for (const m of content.matchAll(/from\s+['"](\.[^'"]+)['"]/g)) {
    specifiers.push(m[1]);
  }
  for (const m of content.matchAll(/(?:^|\n)\s*import\s+['"](\.[^'"]+)['"]/g)) {
    specifiers.push(m[1]);
  }
  return specifiers;
}

/** Resolves a relative specifier against its importer's repo-relative path, mapping `.js` back to `.ts` (this also covers `/index.js` → `/index.ts`, a plain instance of the same rule). */
function resolveRelativeImport(importerRepoPath: string, specifier: string): string {
  const importerDir = path.posix.dirname(importerRepoPath);
  const joined = path.posix.join(importerDir, specifier);
  return joined.endsWith('.js') ? `${joined.slice(0, -'.js'.length)}.ts` : joined;
}

/** Returns the set of repo-relative source files reached from `entryRepoPath`, transitively. */
function walkImportGraph(entryRepoPath: string, visited: Set<string> = new Set()): Set<string> {
  if (visited.has(entryRepoPath)) return visited;
  visited.add(entryRepoPath);

  const absolutePath = path.join(REPO_ROOT, entryRepoPath);
  const content = fs.readFileSync(absolutePath, 'utf-8');

  for (const specifier of extractRelativeSpecifiers(content)) {
    walkImportGraph(resolveRelativeImport(entryRepoPath, specifier), visited);
  }

  return visited;
}

describe('import graph — public entry-point layering', () => {
  it('"./git" entry point (src/git/index.ts) reaches no module under src/providers/', () => {
    const reached = walkImportGraph('src/git/index.ts');
    const offenders = [...reached].filter((p) => p.startsWith('src/providers/'));
    expect(offenders, `src/git/index.ts reached provider module(s): ${offenders.join(', ')}`).toEqual([]);
  });

  it('root entry point (src/index.ts) reaches no adapter module and not forgeProviders', () => {
    const reached = walkImportGraph('src/index.ts');
    const offenders = [...reached].filter(
      (p) =>
        p.startsWith('src/providers/github/') ||
        p.startsWith('src/providers/gitlab/') ||
        p.startsWith('src/providers/jira/') ||
        p === 'src/providers/forgeProviders.ts',
    );
    expect(offenders, `src/index.ts reached adapter/forgeProviders module(s): ${offenders.join(', ')}`).toEqual([]);
  });

  it('positive control: the walker actually traverses, so the assertions above are not vacuous', () => {
    const reachedProviders = walkImportGraph('src/providers/index.ts');
    expect(reachedProviders.has('src/providers/forgeProviders.ts')).toBe(true);
    expect([...reachedProviders].some((p) => p.startsWith('src/providers/github/'))).toBe(true);
    expect([...reachedProviders].some((p) => p.startsWith('src/providers/gitlab/'))).toBe(true);
    expect([...reachedProviders].some((p) => p.startsWith('src/providers/jira/'))).toBe(true);

    const reachedGit = walkImportGraph('src/git/index.ts');
    expect(reachedGit.size).toBeGreaterThan(1);
  });
});

/**
 * Builds the package, verifies the packed tarball ships no `src/`, then
 * installs the real tarball into a clean temp consumer and resolves all
 * three public subpaths under both Node and Bun. Dependency-free (Node
 * built-ins only) so it runs on a bare CI runner. Run via `bun run smoke:package`.
 */
import { execFileSync, execSync } from 'node:child_process';
import * as fs from 'node:fs';
import * as os from 'node:os';
import * as path from 'node:path';
import { fileURLToPath } from 'node:url';

const REPO_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');

interface PackEntry {
  filename: string;
  files: Array<{ path: string }>;
}

function run(cmd: string, cwd: string = REPO_ROOT): string {
  return execSync(cmd, { cwd, encoding: 'utf-8', stdio: ['ignore', 'pipe', 'pipe'] });
}

function fail(message: string): never {
  console.error(`FAIL: ${message}`);
  process.exit(1);
}

function assertFileExists(absPath: string, label: string): void {
  if (!fs.existsSync(absPath)) fail(`expected ${label} to exist`);
}

function main(): void {
  console.log('==> bun run build');
  run('bun run build');

  console.log('==> asserting dist/ entry points and declarations exist');
  for (const relPath of [
    'dist/index.js',
    'dist/index.d.ts',
    'dist/providers/index.js',
    'dist/providers/index.d.ts',
    'dist/git/index.js',
    'dist/git/index.d.ts',
  ]) {
    assertFileExists(path.join(REPO_ROOT, relPath), relPath);
  }

  console.log('==> npm pack --dry-run --json');
  const dryRun = JSON.parse(run('npm pack --dry-run --json')) as PackEntry[];
  const packedPaths = dryRun[0]?.files.map((f) => f.path) ?? [];
  const srcOffenders = packedPaths.filter((p) => p.startsWith('src/'));
  if (srcOffenders.length > 0) fail(`tarball would include src/ files: ${srcOffenders.join(', ')}`);
  if (!packedPaths.includes('README.md')) fail('tarball is missing README.md');
  if (!packedPaths.includes('LICENSE')) fail('tarball is missing LICENSE');

  const packDir = fs.mkdtempSync(path.join(os.tmpdir(), 'devplatform-pack-'));
  const consumerDir = fs.mkdtempSync(path.join(os.tmpdir(), 'devplatform-consumer-'));

  try {
    console.log('==> npm pack --pack-destination <tmpdir>');
    const packed = JSON.parse(run(`npm pack --pack-destination "${packDir}" --json`)) as PackEntry[];
    const tarballName = packed[0]?.filename;
    if (!tarballName) fail('npm pack did not report a tarball filename');
    const tarballPath = path.join(packDir, tarballName);
    assertFileExists(tarballPath, tarballPath);

    console.log(`==> installing tarball into fresh consumer at ${consumerDir}`);
    fs.writeFileSync(
      path.join(consumerDir, 'package.json'),
      JSON.stringify({ name: 'devplatform-smoke-consumer', version: '0.0.0', private: true, type: 'module' }, null, 2),
    );
    run(`npm install "${tarballPath}"`, consumerDir);

    const importCheck = [
      "import * as root from '@paysdoc/devplatform';",
      "import * as providers from '@paysdoc/devplatform/providers';",
      "import * as git from '@paysdoc/devplatform/git';",
      "if (typeof root.BoardStatus === 'undefined') throw new Error('root entry missing BoardStatus');",
      "if (typeof providers.forgeProviders !== 'function') throw new Error('providers entry missing forgeProviders');",
      "if (typeof git.GitContext !== 'function') throw new Error('git entry missing GitContext');",
      "console.log('OK');",
    ].join('\n');

    console.log('==> node consumer (node --input-type=module -e ...)');
    const nodeOut = execFileSync('node', ['--input-type=module', '-e', importCheck], { cwd: consumerDir, encoding: 'utf-8' });
    if (!nodeOut.includes('OK')) fail(`node consumer did not print OK: ${nodeOut}`);

    console.log('==> bun consumer (bun -e ...)');
    const bunOut = execFileSync('bun', ['-e', importCheck], { cwd: consumerDir, encoding: 'utf-8' });
    if (!bunOut.includes('OK')) fail(`bun consumer did not print OK: ${bunOut}`);

    console.log('OK: build, pack, and Node + Bun consumer smoke checks all passed');
  } finally {
    fs.rmSync(consumerDir, { recursive: true, force: true });
    fs.rmSync(packDir, { recursive: true, force: true });
  }
}

try {
  main();
} catch (error) {
  fail(error instanceof Error ? error.message : String(error));
}

